CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, firstName VARCHAR(100), secondName VARCHAR(100), organisation VARCHAR(255), role VARCHAR(50));
CREATE TABLE IF NOT EXISTS warehouses (id INT AUTO_INCREMENT PRIMARY KEY, location VARCHAR(255) NOT NULL, capacity INT, transport VARCHAR(255), contactEmail VARCHAR(255), contactPhone VARCHAR(50));
CREATE TABLE IF NOT EXISTS shipments (id INT AUTO_INCREMENT PRIMARY KEY, sourceWarehouse INT, description TEXT, quantity INT, destination TEXT, transportProvider VARCHAR(255), status VARCHAR(50), createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (sourceWarehouse) REFERENCES warehouses(id) ON DELETE SET NULL);
